<?php declare(strict_types=1); namespace App\Model\Table; use Cake\ORM\Table; use Cake\Validation\Validator; class PagosParqueaderosTable extends Table { /** Configures parking payments. */ public function initialize(array $config):void { parent::initialize($config);$this->setTable('pagos_parqueaderos');$this->belongsTo('AsignacionesParqueaderos',['foreignKey'=>'asignacion_parqueadero_id']); } /** Validates parking payments. */ public function validationDefault(Validator $v):Validator { return $v->integer('asignacion_parqueadero_id')->notEmptyString('asignacion_parqueadero_id')->notEmptyString('period')->maxLength('period',7)->date('due_date',['ymd'])->notEmptyDate('due_date')->date('payment_date',['ymd'])->allowEmptyDate('payment_date')->decimal('amount_due')->decimal('amount_paid'); } }
